  <style>
    .fcx{font-family:var(--font-body,'Inter',sans-serif);color:var(--slate-body,#333)}
    .fcx *{box-sizing:border-box}
    .fcx-wrap{max-width:1140px;margin:0 auto;padding:0 16px}
    .fcx h2,.fcx h3,.fcx summary{letter-spacing:normal;word-spacing:.08em}
    .fcx-band{padding:64px 0}
    .fcx-band--alt{background:var(--bg-light,#F8FAFC);border-top:1px solid var(--border-light,#E2E8F0);border-bottom:1px solid var(--border-light,#E2E8F0)}
    .fcx h2{font-family:var(--font-heading,'Plus Jakarta Sans',sans-serif);font-size:clamp(1.4rem,2.6vw,2rem);font-weight:800;color:var(--slate-charcoal,#1A1A1A);line-height:1.25;margin:0 0 18px;position:relative;padding-bottom:14px}
    .fcx h2::after{content:"";position:absolute;left:0;bottom:0;width:56px;height:4px;border-radius:4px;background:var(--grad-primary,linear-gradient(135deg,#D9251D,#F0453D))}
    .fcx-center{text-align:center}
    .fcx-center h2::after{left:50%;transform:translateX(-50%)}
    .fcx h3{font-family:var(--font-heading,'Plus Jakarta Sans',sans-serif);font-size:1.08rem;font-weight:700;color:var(--slate-charcoal,#1A1A1A);margin:0 0 8px}
    .fcx p,.fcx li{line-height:1.8;font-size:1rem;color:var(--slate-body,#333);text-align:left}
    .fcx p,.fcx li{text-align:left!important;hyphens:none!important;-webkit-hyphens:none!important;word-spacing:normal}
    .fcx p{margin:0 0 14px}
    .fcx p:last-child{margin-bottom:0}
    .fcx-lead{max-width:820px;margin:0 auto 28px}
    .fcx-center .fcx-lead{text-align:center}

    /* two panels */
    .fcx-duo{display:grid;grid-template-columns:1fr 1fr;gap:24px}
    .fcx-panel{background:#fff;border:1px solid var(--border-light,#E2E8F0);border-radius:18px;padding:30px;box-shadow:var(--shadow-sm,0 4px 15px rgba(217,37,29,.05));position:relative;overflow:hidden}
    .fcx-panel::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:var(--grad-primary,linear-gradient(135deg,#D9251D,#F0453D))}
    .fcx-panel h2{font-size:clamp(1.2rem,2vw,1.5rem)}
    .fcx-ico{width:52px;height:52px;border-radius:14px;display:inline-flex;align-items:center;justify-content:center;background:rgba(217,37,29,.08);color:var(--brand-red,#D9251D);font-size:22px;margin-bottom:16px;flex-shrink:0}

    /* cards */
    .fcx-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
    .fcx-card{background:#fff;border:1px solid var(--border-light,#E2E8F0);border-radius:16px;padding:26px 22px;transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease}
    .fcx-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg,0 20px 50px rgba(217,37,29,.14));border-color:var(--border-accent,rgba(217,37,29,.18))}
    .fcx-card p{font-size:.95rem;line-height:1.7}

    /* spec table */
    .fcx-spec{display:grid;grid-template-columns:1.1fr .9fr;gap:32px;align-items:center}
    .fcx-table{width:100%;border-collapse:separate;border-spacing:0;border-radius:16px;overflow:hidden;background:#fff;box-shadow:var(--shadow-md,0 10px 30px rgba(217,37,29,.09));border:1px solid var(--border-light,#E2E8F0)}
    .fcx-table th,.fcx-table td{padding:14px 18px;text-align:left;font-size:.97rem;border-bottom:1px solid var(--border-subtle,#F1F5F9)}
    .fcx-table tr:last-child th,.fcx-table tr:last-child td{border-bottom:0}
    .fcx-table th{width:42%;font-weight:700;color:var(--slate-charcoal,#1A1A1A);background:var(--bg-light,#F8FAFC);border-left:4px solid var(--brand-red,#D9251D)}
    .fcx-table tr:nth-child(even) td{background:#FCFCFD}
    .fcx-note{background:#fff;border:1px dashed var(--border-accent,rgba(217,37,29,.18));border-radius:16px;padding:26px;display:flex;gap:16px;align-items:flex-start}
    .fcx-note .fcx-ico{margin:0}

    /* text blocks */
    .fcx-blocks{display:grid;grid-template-columns:1fr 1fr;gap:24px}
    .fcx-block{background:#fff;border-radius:16px;padding:28px;border:1px solid var(--border-light,#E2E8F0);border-left:5px solid var(--brand-red,#D9251D)}
    .fcx-block h2{font-size:clamp(1.15rem,1.8vw,1.4rem);padding-bottom:0}
    .fcx-block h2::after{display:none}

    /* checklist */
    .fcx-checks{list-style:none;margin:0 0 20px;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}
    .fcx-checks li{background:#fff;border:1px solid var(--border-light,#E2E8F0);border-radius:12px;padding:12px 14px 12px 44px;position:relative;font-weight:600;color:var(--slate-charcoal,#1A1A1A);line-height:1.4;font-size:.95rem}
    .fcx-checks li::before{content:"\f00c";font-family:"Font Awesome 6 Free";font-weight:900;position:absolute;left:14px;top:50%;transform:translateY(-50%);width:20px;height:20px;border-radius:50%;background:var(--brand-red,#D9251D);color:#fff;font-size:10px;display:flex;align-items:center;justify-content:center}

    /* dark callout */
    .fcx-callout{background:var(--grad-dark,linear-gradient(135deg,#1A1A1A,#111));border-radius:20px;padding:40px;display:flex;gap:24px;align-items:flex-start;position:relative;overflow:hidden}
    .fcx-callout::after{content:"";position:absolute;right:-60px;top:-60px;width:220px;height:220px;border-radius:50%;background:rgba(217,37,29,.25);filter:blur(10px)}
    .fcx-callout h2,.fcx-callout p{color:#fff;position:relative;z-index:1}
    .fcx-callout p{color:rgba(255,255,255,.85)}
    .fcx-callout .fcx-ico{background:rgba(255,255,255,.1);color:#fff;position:relative;z-index:1}

    /* FAQ */
    .fcx-faq{max-width:880px;margin:0 auto}
    .fcx-faq details{background:#fff;border:1px solid var(--border-light,#E2E8F0);border-radius:14px;margin:0 0 12px;transition:box-shadow .2s ease,border-color .2s ease}
    .fcx-faq details[open]{border-color:var(--border-accent,rgba(217,37,29,.18));box-shadow:var(--shadow-md,0 10px 30px rgba(217,37,29,.09))}
